SELECT txn_month, amount_bucket, 7_eleven_count FROM (SELECT MONTH(txn_time) AS txn_month, CASE WHEN amount >= 3500 THEN 'high' WHEN amount >= 2000 THEN 'mid' ELSE 'low' END AS amount_bucket, COUNT(CASE WHEN merchant = '7-Eleven' THEN 1 END) AS 7_eleven_count FROM transactions GROUP BY MONTH(txn_time), CASE WHEN amount >= 3500 THEN 'high' WHEN amount >= 2000 THEN 'mid' ELSE 'low' END) AS t WHERE 7_eleven_count < 6 ORDER BY amount_bucket DESC;
